public static void main(String[] args){
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int[][] result = new int[n][n];
    char dir = 'R';
    int max = n * n - 1;
    int[] xDir = {0, 1, 0, -1};
    int[] yDir = {1, 0, -1, 0};
    int tmpDir = 0;
    int x = (n - 1) / 2;
    int y = (n - 1) / 2;
    result[x][y] = -1; // Takahashi is at the center

    int tmp = 1;
    while (tmp <= max) {
        int nextX = x + xDir[tmpDir];
        int nextY = y + yDir[tmpDir];
        if (nextX >= 0 && nextX < n && nextY >= 0 && nextY < n && result[nextX][nextY] == 0) {
            // Continue in the same direction
        } else {
            // Change direction
            tmpDir = (tmpDir + 1) % 4;
        }
        x += xDir[tmpDir];
        y += yDir[tmpDir];
        result[x][y] = tmp;
        tmp++;
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (result[i][j] == -1) {
                System.out.print("T" + " ");
            } else {
                System.out.print(result[i][j] + " ");
            }
        }
        System.out.println("");
    }
}
